insert into activities (id, domain, age_band, title, why, duration_minutes, duration_label, materials, instructions, benefit, source) values
  ('acoustic-science-y5_3', 'cognitive'::domain, 'y5_3'::age_band, 'Acoustic Science', 'A practical challenge that builds auditory discrimination.', 13, '10–15 min', 'Two cups, string', 'Two cups connected by a taut string. Sound travels through the string: demonstrate vibration as a medium of sound.', 'Sensory-rich activity gives children a break from cognitive demand while still developing skill. Expect them to want to do it their own way, and let them where you can.', 'AOTA Sensory Integration; Ayres Sensory Integration framework; IAP'),
  ('own-study-schedule-y5_3', 'social_emotional'::domain, 'y5_3'::age_band, 'Own Study Schedule', 'An activity that develops organising self and belongings.', 13, '10–15 min', 'Paper + calendar', 'Plan a weekly study schedule independently. What to revise, when, for how long. Executive function for academic contexts.', 'Children who genuinely contribute at home tend to be more capable and more confident. Talk about how they approached it rather than whether they got it right; the strategy is the valuable part.', 'AOTA Activities of Daily Living; NCERT Foundational Stage; IAP'),
  ('solo-public-transaction-y5_3', 'social_emotional'::domain, 'y5_3'::age_band, 'Solo Public Transaction', 'A practical challenge that builds handling money.', 13, '10–15 min', 'Money for a small purchase', 'Enter a shop, choose an item, pay, check change, thank the cashier: alone. Real-world social-financial independence.', 'This develops the organisation and self-management that school increasingly demands. Expect them to want to do it their own way, and let them where you can.', 'AOTA Activities of Daily Living; NCERT Foundational Stage; IAP'),
  ('badminton-y5_6', 'motor'::domain, 'y5_6'::age_band, 'Badminton', 'An activity that develops coordination, strength and control.', 13, '10–15 min', 'Badminton rackets + shuttlecock (or improvised)', 'Rally a shuttlecock back and forth. Eye-hand coordination + fast visual tracking + footwork combined.', 'This refines coordination and control, and gives your child the physical competence that sport and play at school will draw on. Let your child attempt it independently first, and offer help only when they ask or genuinely stall.', 'WHO Physical Activity Guidelines (5–17); AAP Sports and Fitness; IAP'),
  ('handstand-walk-y5_6', 'motor'::domain, 'y5_6'::age_band, 'Handstand Walk', 'An activity that develops advanced balance and control.', 7, '5–8 min', 'Clear wall', 'From wall-handstand, try 1–2 hand-steps away from wall. Weight shift in full inversion = exceptional balance demand.', 'This refines coordination and control, and gives your child the physical competence that sport and play at school will draw on. Expect them to want to do it their own way, and let them where you can.', 'WHO Physical Activity Guidelines (5–17); AAP Sports and Fitness; IAP'),
  ('swim-50-metres-y5_6', 'motor'::domain, 'y5_6'::age_band, 'Swim 50 Metres', 'An activity that develops swimming technique.', 18, '15–20 min', 'Swimming pool', 'Always with a trained adult or lifeguard present, swim 50 metres using 2 different strokes. Stroke transition demonstrates fluid motor switching.', 'Skills at this age become more accurate and more strategic, and this is the kind of practice that develops both. Talk about how they approached it rather than whether they got it right; the strategy is the valuable part.', 'AAP Water Safety; Indian Swimming Federation basic safety norms; IAP'),
  ('bicycle-long-distance-y5_6', 'motor'::domain, 'y5_6'::age_band, 'Bicycle Long Distance', 'An activity that develops cycling skill and road awareness.', 25, '20–30 min', 'Bicycle', 'Cycle 5 km on a chosen route. Stamina, navigation, and sustained attention across 20–30 minutes.', 'This refines coordination and control, and gives your child the physical competence that sport and play at school will draw on. Let your child attempt it independently first, and offer help only when they ask or genuinely stall.', 'WHO Physical Activity Guidelines (5–17); AAP Sports and Fitness; IAP'),
  ('cricket-bowling-y5_6', 'motor'::domain, 'y5_6'::age_band, 'Cricket Bowling', 'A practical challenge that builds running speed and endurance.', 13, '10–15 min', 'Ball + target', 'Overarm bowling at a target (stump or cone). Run-up + release + follow-through = full-body coordination in sequence.', 'This refines coordination and control, and gives your child the physical competence that sport and play at school will draw on. Talk about how they approached it rather than whether they got it right; the strategy is the valuable part.', 'WHO Physical Activity Guidelines (5–17); AAP Sports and Fitness; IAP'),
  ('gymnastics-beam-y5_6', 'motor'::domain, 'y5_6'::age_band, 'Gymnastics Beam', 'A practical challenge that builds advanced balance and control.', 13, '10–15 min', 'Low beam or plank (10 cm high)', 'Walk, turn, pose on a low beam. Balance in one plane while planning movement = gymnastic spatial reasoning.', 'Skills at this age become more accurate and more strategic, and this is the kind of practice that develops both. Let your child attempt it independently first, and offer help only when they ask or genuinely stall.', 'WHO Physical Activity Guidelines (5–17); AAP Sports and Fitness; IAP'),
  ('archery-i-y5_6', 'motor'::domain, 'y5_6'::age_band, 'Archery I', 'A practical challenge that builds throwing, catching and aiming accuracy.', 13, '10–15 min', 'Simple bow and arrows (safe set)', 'Simple rubber-band bow and arrow or a commercial safety set. Aim, hold breath, release. Fine + gross combined.', 'Physical activity now supports concentration, sleep and mood as much as it supports strength. Talk about how they approached it rather than whether they got it right; the strategy is the valuable part.', 'WHO Physical Activity Guidelines (5–17); AAP Sports and Fitness; IAP'),
  ('frisbee-accurate-throw-y5_6', 'motor'::domain, 'y5_6'::age_band, 'Frisbee Accurate Throw', 'A skill-building activity focused on throwing, catching and aiming accuracy.', 13, '10–15 min', 'Frisbee', 'Throw a frisbee so it lands in a target area 10 m away. Wrist flip + horizontal plane release = distinct motor skill.', 'Skills at this age become more accurate and more strategic, and this is the kind of practice that develops both. Expect them to want to do it their own way, and let them where you can.', 'WHO Physical Activity Guidelines (5–17); AAP Sports and Fitness; IAP'),
  ('short-story-collection-y5_6', 'motor'::domain, 'y5_6'::age_band, 'Short Story Collection', 'A skill-building activity focused on handwriting control.', 25, '20–30 min', 'Pencil and paper', '3 short stories (200 words each) with a connecting theme. Organisation + variety within a unified project.', 'The hand skills built here support handwriting, and handwriting fluency frees up attention for thinking. Let your child attempt it independently first, and offer help only when they ask or genuinely stall.', 'AOTA Fine Motor Development; NCERT Foundational Literacy; IAP'),
  ('macrame-y5_6', 'motor'::domain, 'y5_6'::age_band, 'Macrame', 'A practical challenge that builds needle skills and precision.', 25, '20–30 min', 'Macrame cord or thick string', 'Square knot and half-hitch repeatedly to make a small wall piece or bracelet. Pattern knotting = fine motor + sequencing.', 'This refines the precision your child now needs for writing, drawing and detailed work at school. Talk about how they approached it rather than whether they got it right; the strategy is the valuable part.', 'AOTA Fine Motor Development; NCERT Foundational Literacy; IAP'),
  ('perspective-drawing-i-y5_6', 'motor'::domain, 'y5_6'::age_band, 'Perspective Drawing I', 'A practical challenge that builds drawing accuracy and detail.', 18, '15–20 min', 'Pencil, ruler, paper', 'One-point perspective: a road or corridor disappearing to a single point on the horizon. Geometry through art.', 'The hand skills built here support handwriting, and handwriting fluency frees up attention for thinking. Expect them to want to do it their own way, and let them where you can.', 'AOTA Fine Motor Development; NCERT Foundational Literacy; IAP'),
  ('build-hydraulic-arm-y5_6', 'motor'::domain, 'y5_6'::age_band, 'Build Hydraulic Arm', 'An activity that develops construction and spatial precision.', 25, '20–30 min', 'Syringes, tubing, card, tape', 'Syringes filled with water and connected by tubing. Hydraulic pressure lifts a load. Engineering + fluid physics.', 'This refines the precision your child now needs for writing, drawing and detailed work at school. Talk about how they approached it rather than whether they got it right; the strategy is the valuable part.', 'AOTA Fine Motor Development; NCERT Foundational Literacy; IAP'),
  ('scratch-coding-y5_6', 'motor'::domain, 'y5_6'::age_band, 'Scratch Coding', 'A practical challenge that builds fine motor precision and control.', 18, '15–20 min', 'Computer with Scratch (scratch.mit.edu)', 'Program a character to move, make a sound, and respond to a key press. Three functions in one project = logic thinking.', 'The hand skills built here support handwriting, and handwriting fluency frees up attention for thinking. Let your child attempt it independently first, and offer help only when they ask or genuinely stall.', 'AOTA Fine Motor Development; NCERT Foundational Literacy; IAP'),
  ('print-making-y5_6', 'motor'::domain, 'y5_6'::age_band, 'Print-Making', 'A practical challenge that builds construction and spatial precision.', 25, '20–30 min', 'Soft lino or polystyrene, blunt carving tool, paint', 'Carve a simple design into a soft block and print. Carving subtracts; printing reveals: two-stage craft thinking.', 'Fine motor control at this age is about accuracy and endurance rather than basic ability. Expect them to want to do it their own way, and let them where you can.', 'AOTA Fine Motor Development; NCERT Foundational Literacy; IAP'),
  ('read-novel-series-y5_6', 'communication'::domain, 'y5_6'::age_band, 'Read Novel Series', 'A skill-building activity focused on reading development.', 25, '20–30 min', 'Novel series (2 books)', 'Two books in a series. Tracking character development across books = long-form narrative memory.', 'This supports the vocabulary and expression that school will increasingly demand. Let your child attempt it independently first, and offer help only when they ask or genuinely stall.', 'ASHA Speech and Language Milestones; NCERT Foundational Literacy and Numeracy; IAP'),
  ('from-another-perspective-y5_6', 'communication'::domain, 'y5_6'::age_band, 'from Another Perspective', 'An activity that develops reading development.', 18, '15–20 min', 'Pencil and paper + familiar book', 'Retell a chapter from a book from a different character''s point of view. Perspective-taking through creative writing.', 'Being able to explain their thinking out loud helps children organise it, which is why talk matters at this age. Expect them to want to do it their own way, and let them where you can.', 'ASHA Speech and Language Milestones; NCERT Foundational Literacy and Numeracy; IAP'),
  ('homophone-homonym-work-y5_6', 'communication'::domain, 'y5_6'::age_band, 'Homophone Homonym Work', 'A practical challenge that builds language, literacy and expression.', 8, '5–10 min', 'None', 'Their/there/they''re, to/too/two, affect/effect. Context determines the correct form. Language precision.', 'Language now becomes a tool for thinking, explaining and reading, and this strengthens all three. Let your child attempt it independently first, and offer help only when they ask or genuinely stall.', 'WHO Screen Time Guidelines (under 5); IAP Screen Time Guidance; IAP'),
  ('interview-transcribe-y5_6', 'communication'::domain, 'y5_6'::age_band, 'Interview Transcribe', 'A practical challenge that builds conversation and presentation.', 18, '15–20 min', 'Paper for notes or recording device', 'Interview a family member for 5 minutes; transcribe key quotes. Journalism skill: listening + note-taking + selection.', 'Language now becomes a tool for thinking, explaining and reading, and this strengthens all three. Let your child attempt it independently first, and offer help only when they ask or genuinely stall.', 'ASHA Speech and Language Milestones; NCERT Foundational Literacy and Numeracy; IAP'),
  ('read-review-film-y5_6', 'communication'::domain, 'y5_6'::age_band, 'Read Review Film', 'A practical challenge that builds reading development.', 18, '15–20 min', 'Paper and pencil', 'Watch a film; write a 200-word review: plot summary, best element, weakest element, rating. Critical media literacy.', 'This supports the vocabulary and expression that school will increasingly demand. Let your child attempt it independently first, and offer help only when they ask or genuinely stall.', 'ASHA Speech and Language Milestones; NCERT Foundational Literacy and Numeracy; IAP'),
  ('word-etymology-project-y5_6', 'communication'::domain, 'y5_6'::age_band, 'Word Etymology Project', 'A skill-building activity focused on vocabulary depth.', 13, '10–15 min', 'Dictionary or etymology book', 'Choose 5 unusual words and find their origins. Etymology shows language as a living, evolving system.', 'This supports the vocabulary and expression that school will increasingly demand. Expect them to want to do it their own way, and let them where you can.', 'ASHA Speech and Language Milestones; NCERT Foundational Literacy and Numeracy; IAP'),
  ('write-acrostic-poem-y5_6', 'communication'::domain, 'y5_6'::age_band, 'Write Acrostic Poem', 'An activity that develops written expression.', 13, '10–15 min', 'Pencil and paper', 'Write a poem where the first letter of each line spells a word. Constraint-based creativity = high linguistic challenge.', 'Language now becomes a tool for thinking, explaining and reading, and this strengthens all three. Talk about how they approached it rather than whether they got it right; the strategy is the valuable part.', 'ASHA Speech and Language Milestones; NCERT Foundational Literacy and Numeracy; IAP'),
  ('comprehension-inference-y5_6', 'communication'::domain, 'y5_6'::age_band, 'Comprehension Inference', 'An activity that develops reading development.', 13, '10–15 min', 'Any passage with inferrable subtext', 'Read a passage and answer: ''The text says X. What does that suggest about Y?'' Implicit meaning = deep comprehension.', 'Language now becomes a tool for thinking, explaining and reading, and this strengthens all three. Let your child attempt it independently first, and offer help only when they ask or genuinely stall.', 'ASHA Speech and Language Milestones; NCERT Foundational Literacy and Numeracy; IAP'),
  ('percentages-y5_6', 'cognitive'::domain, 'y5_6'::age_band, 'Percentages', 'An activity that develops reasoning, planning and problem-solving.', 8, '5–10 min', 'Objects to split into 100 or 10', '50% = half. 25% = quarter. 10% = one tenth. Percentage as a fraction of 100: connect to known fraction knowledge.', 'Understanding at this stage grows from working things out rather than being told the answer. Let your child attempt it independently first, and offer help only when they ask or genuinely stall.', 'NCERT Foundational Literacy and Numeracy; Harvard Center on the Developing Child; IAP'),
  ('negative-numbers-y5_6', 'cognitive'::domain, 'y5_6'::age_band, 'Negative Numbers', 'An activity that develops number and early mathematical thinking.', 7, '5–8 min', 'Extended number line drawn on paper', 'Numbers below zero: temperature, floors below ground, money owed. Number line extended below zero.', 'This develops the planning and reasoning that increasingly demanding schoolwork will require. Talk about how they approached it rather than whether they got it right; the strategy is the valuable part.', 'NCERT Foundational Literacy and Numeracy; Harvard Center on the Developing Child; IAP'),
  ('area-rectangle-y5_6', 'cognitive'::domain, 'y5_6'::age_band, 'Area Rectangle', 'An activity that develops reasoning, planning and problem-solving.', 8, '5–10 min', 'Ruler, paper for recording', 'Length × width. Find the area of 5 household objects. Area as ''how many squares fill this shape.''', 'At this age children can genuinely think through a problem, and doing so builds the habit of persisting with hard things. Expect them to want to do it their own way, and let them where you can.', 'NCERT Foundational Literacy and Numeracy; Harvard Center on the Developing Child; IAP'),
  ('electricity-magnetism-y5_6', 'cognitive'::domain, 'y5_6'::age_band, 'Electricity Magnetism', 'An activity that develops scientific reasoning.', 18, '15–20 min', 'Wire, nail, battery', 'Electromagnet: coil wire around a nail + battery = magnet. What does it attract? Science + engineering combined.', 'This develops the planning and reasoning that increasingly demanding schoolwork will require. Expect them to want to do it their own way, and let them where you can.', 'NCERT Foundational Literacy and Numeracy; Harvard Center on the Developing Child; IAP'),
  ('human-body-systems-y5_6', 'cognitive'::domain, 'y5_6'::age_band, 'Human Body Systems', 'A skill-building activity focused on reasoning, planning and problem-solving.', 13, '10–15 min', 'Paper and coloured pens', 'Skeleton, muscles, heart, lungs. Draw and label each system. How do systems work together?', 'Understanding at this stage grows from working things out rather than being told the answer. Talk about how they approached it rather than whether they got it right; the strategy is the valuable part.', 'NCERT Foundational Literacy and Numeracy; Harvard Center on the Developing Child; IAP'),
  ('probability-y5_6', 'cognitive'::domain, 'y5_6'::age_band, 'Probability', 'A skill-building activity focused on scientific reasoning.', 13, '10–15 min', 'Coin + tally chart', 'Flip a coin 20 times: predict, then compare results. Experimental probability vs theoretical probability.', 'This develops the planning and reasoning that increasingly demanding schoolwork will require. Expect them to want to do it their own way, and let them where you can.', 'NCERT Foundational Literacy and Numeracy; Harvard Center on the Developing Child; IAP'),
  ('recognise-unhealthy-relationships-y5_6', 'social_emotional'::domain, 'y5_6'::age_band, 'Recognise Unhealthy Relationships', 'An activity that develops friendship and social navigation.', 13, '10–15 min', 'None', 'What would make a friendship unhealthy? What would you do if that happened?'' Protective relationship literacy.', 'Social and emotional skills at this age predict how school goes as much as academic ability does. Talk about how they approached it rather than whether they got it right; the strategy is the valuable part.', 'CASEL Social-Emotional Framework; NAEYC Developmentally Appropriate Practice; IAP'),
  ('practice-saying-no-y5_6', 'social_emotional'::domain, 'y5_6'::age_band, 'Practice Saying No', 'A skill-building activity focused on social understanding and self-regulation.', 8, '5–10 min', 'None', 'Role-play scenarios where saying no is the right answer. ''No thank you'', ''I don''t want to do that'', ''I''m leaving now.''', 'This supports the friendships, fairness and self-control that become central once children are in a classroom. Let your child attempt it independently first, and offer help only when they ask or genuinely stall.', 'CASEL Social-Emotional Framework; NAEYC Developmentally Appropriate Practice; IAP'),
  ('manage-academic-pressure-y5_6', 'social_emotional'::domain, 'y5_6'::age_band, 'Manage Academic Pressure', 'A skill-building activity focused on responsibility and contribution.', 8, '5–10 min', 'None', 'What does it feel like when you''re worried about doing badly? What helps?'' Anxiety about performance is real and needs a name.', 'This supports the friendships, fairness and self-control that become central once children are in a classroom. Expect them to want to do it their own way, and let them where you can.', 'CASEL Social-Emotional Framework; NAEYC Developmentally Appropriate Practice; IAP'),
  ('digital-empathy-y5_6', 'social_emotional'::domain, 'y5_6'::age_band, 'Digital Empathy', 'An activity that develops empathy and perspective-taking.', 8, '5–10 min', 'None', 'Would you say this in person? How might they feel reading it?'' Online communication carries the same emotional weight.', 'Social and emotional skills at this age predict how school goes as much as academic ability does. Let your child attempt it independently first, and offer help only when they ask or genuinely stall.', 'CASEL Social-Emotional Framework; NAEYC Developmentally Appropriate Practice; IAP'),
  ('gratitude-journal-y5_6', 'social_emotional'::domain, 'y5_6'::age_band, 'Gratitude Journal', 'A skill-building activity focused on social understanding and self-regulation.', 4, '3–5 min', 'Journal + pencil', 'Write or draw 3 things you''re grateful for, every day for 2 weeks. Sustained gratitude practice changes mood baseline.', 'Your child can now reflect on their own behaviour, which makes real emotional learning possible. Talk about how they approached it rather than whether they got it right; the strategy is the valuable part.', 'CASEL Social-Emotional Framework; NAEYC Developmentally Appropriate Practice; IAP'),
  ('cultural-exchange-meal-y5_6', 'social_emotional'::domain, 'y5_6'::age_band, 'Cultural Exchange Meal', 'A practical challenge that builds social understanding and self-regulation.', 38, '30–45 min', 'Ingredients for chosen recipe', 'Cook and eat a meal from a culture your family isn''t from. Research the dish + cooking + context conversation.', 'Your child can now reflect on their own behaviour, which makes real emotional learning possible. Expect them to want to do it their own way, and let them where you can.', 'CASEL Social-Emotional Framework; NAEYC Developmentally Appropriate Practice; IAP'),
  ('optical-illusion-art-y5_6', 'cognitive'::domain, 'y5_6'::age_band, 'Optical Illusion Art', 'An activity that develops sensory art and material handling.', 25, '20–30 min', 'Pencil, ruler, paper', 'Draw Escher-inspired impossible shapes or trompe l''oeil. Visual perception + spatial reasoning + fine motor combined.', 'Physical and sensory input remains important at this age, particularly for children who sit still for long periods at school. Expect them to want to do it their own way, and let them where you can.', 'AOTA Sensory Integration; Ayres Sensory Integration framework; IAP'),
  ('fossil-making-y5_6', 'cognitive'::domain, 'y5_6'::age_band, 'Fossil Making', 'A practical challenge that builds tactile discrimination and refinement.', 18, '15–20 min', 'Clay, shells or leaves', 'Press shells, leaves, or bones into clay; let dry. The impression is exactly how real fossils form. Palaeontology concept.', 'Sensory-rich activity gives children a break from cognitive demand while still developing skill. Let your child attempt it independently first, and offer help only when they ask or genuinely stall.', 'AOTA Sensory Integration; Ayres Sensory Integration framework; IAP'),
  ('make-weather-station-y5_6', 'cognitive'::domain, 'y5_6'::age_band, 'Make Weather Station', 'An activity that develops natural sensory environments.', 25, '20–30 min', 'Containers, ruler, card, pin', 'Thermometer, rain gauge (marked container), wind direction vane (card + pin). Record daily for 2 weeks.', 'Sensory-rich activity gives children a break from cognitive demand while still developing skill. Expect them to want to do it their own way, and let them where you can.', 'AOTA Sensory Integration; Ayres Sensory Integration framework; IAP'),
  ('sound-science-y5_6', 'cognitive'::domain, 'y5_6'::age_band, 'Sound Science', 'An activity that develops sensory exploration through water.', 13, '10–15 min', 'Glasses, water, spoon', 'Partially fill glasses with water at different levels; tap each. More water = lower pitch. Frequency + resonance explained.', 'This supports regulation and focus, which matters more once formal learning begins. Talk about how they approached it rather than whether they got it right; the strategy is the valuable part.', 'AOTA Sensory Integration; Ayres Sensory Integration framework; IAP'),
  ('or-chicken-wing-y5_6', 'cognitive'::domain, 'y5_6'::age_band, 'or Chicken Wing', 'A practical challenge that builds sensory art and material handling.', 18, '15–20 min', 'Squid or chicken wing, disposable gloves', 'Supervised dissection of a squid (from market) or chicken wing. Identify tendons, cartilage, muscle. Real biology.', 'This supports regulation and focus, which matters more once formal learning begins. Expect them to want to do it their own way, and let them where you can.', 'AOTA Sensory Integration; Ayres Sensory Integration framework; IAP'),
  ('plan-fundraiser-y5_6', 'social_emotional'::domain, 'y5_6'::age_band, 'Plan Fundraiser', 'A practical challenge that builds organising self and belongings.', 18, '15–20 min', 'Paper for planning', 'Choose a cause; plan a simple fundraiser: what, for whom, how much to raise, how to tell people. Civic planning.', 'Independence and responsibility at this age build competence that carries well beyond the specific task. Talk about how they approached it rather than whether they got it right; the strategy is the valuable part.', 'AOTA Activities of Daily Living; NCERT Foundational Stage; IAP'),
  ('travel-independently-y5_6', 'social_emotional'::domain, 'y5_6'::age_band, 'Travel Independently', 'A skill-building activity focused on personal safety and judgement.', 18, '15–20 min', 'Transport money if needed', 'Public transport or walk for a familiar route without adult. Route knowledge + safety + agency growing together.', 'Independence and responsibility at this age build competence that carries well beyond the specific task. Expect them to want to do it their own way, and let them where you can.', 'AOTA Activities of Daily Living; NCERT Foundational Stage; IAP'),
  ('football-y5_9', 'motor'::domain, 'y5_9'::age_band, 'Football', 'A practical challenge that builds ball control with the feet.', 25, '20–30 min', 'Football + players', 'Understand and play a position in a simple football match. Reading the game spatially is as important as individual skill.', 'This refines coordination and control, and gives your child the physical competence that sport and play at school will draw on. Let your child attempt it independently first, and offer help only when they ask or genuinely stall.', 'WHO Physical Activity Guidelines (5–17); AAP Sports and Fitness; IAP'),
  ('swimming-race-y5_9', 'motor'::domain, 'y5_9'::age_band, 'Swimming Race', 'An activity that develops running speed and endurance.', 18, '15–20 min', 'Swimming pool', 'Race against another person or own previous time. Performance awareness + competitive experience in a safe context.', 'Skills at this age become more accurate and more strategic, and this is the kind of practice that develops both. Let your child attempt it independently first, and offer help only when they ask or genuinely stall.', 'AAP Water Safety; Indian Swimming Federation basic safety norms; IAP'),
  ('bicycle-navigation-y5_9', 'motor'::domain, 'y5_9'::age_band, 'Bicycle Navigation', 'A skill-building activity focused on cycling skill and road awareness.', 18, '15–20 min', 'Bicycle + route map', 'Navigate a 2-km route from memory or a simple map, independently or with a peer.', 'Physical activity now supports concentration, sleep and mood as much as it supports strength. Expect them to want to do it their own way, and let them where you can.', 'WHO Physical Activity Guidelines (5–17); AAP Sports and Fitness; IAP'),
  ('rock-climbing-i-y5_9', 'motor'::domain, 'y5_9'::age_band, 'Rock Climbing I', 'An activity that develops climbing and whole-body strength.', 25, '20–30 min', 'Climbing wall + instructor', 'Supervised rock climbing on a wall or crag. Reading the route + executing the movement + trusting the equipment.', 'Skills at this age become more accurate and more strategic, and this is the kind of practice that develops both. Talk about how they approached it rather than whether they got it right; the strategy is the valuable part.', 'WHO Physical Activity Guidelines (5–17); AAP Sports and Fitness; IAP'),
  ('trampoline-y5_9', 'motor'::domain, 'y5_9'::age_band, 'Trampoline', 'A practical challenge that builds coordination, strength and control.', 13, '10–15 min', 'Trampoline (supervised)', 'Seat drop and back drop on a trampoline (supervised). Full inversion trust + controlled landing on novel body part.', 'Physical activity now supports concentration, sleep and mood as much as it supports strength. Let your child attempt it independently first, and offer help only when they ask or genuinely stall.', 'WHO Physical Activity Guidelines (5–17); AAP Sports and Fitness; IAP'),
  ('tennis-y5_9', 'motor'::domain, 'y5_9'::age_band, 'Tennis', 'A skill-building activity focused on swimming technique.', 13, '10–15 min', 'Tennis racket and ball (or improvised)', 'Rally with forehand and backhand groundstrokes. Switching grip and swing direction is a bilateral motor distinction.', 'Physical activity now supports concentration, sleep and mood as much as it supports strength. Expect them to want to do it their own way, and let them where you can.', 'WHO Physical Activity Guidelines (5–17); AAP Sports and Fitness; IAP'),
  ('sprint-technique-y5_9', 'motor'::domain, 'y5_9'::age_band, 'Sprint Technique', 'A skill-building activity focused on running speed and endurance.', 8, '5–10 min', 'Open space', 'Arms, legs, lean, breathing: all coordinated in a maximal effort sprint. Physical literacy = understanding your own body.', 'This refines coordination and control, and gives your child the physical competence that sport and play at school will draw on. Let your child attempt it independently first, and offer help only when they ask or genuinely stall.', 'WHO Physical Activity Guidelines (5–17); AAP Sports and Fitness; IAP'),
  ('cricket-batting-y5_9', 'motor'::domain, 'y5_9'::age_band, 'Cricket Batting', 'A practical challenge that builds climbing and whole-body strength.', 13, '10–15 min', 'Cricket bat and ball', 'Bat against a bowled delivery with proper stance, backlift, and follow-through.', 'Physical activity now supports concentration, sleep and mood as much as it supports strength. Let your child attempt it independently first, and offer help only when they ask or genuinely stall.', 'WHO Physical Activity Guidelines (5–17); AAP Sports and Fitness; IAP'),
  ('write-personal-essay-y5_9', 'motor'::domain, 'y5_9'::age_band, 'Write Personal Essay', 'A skill-building activity focused on handwriting control.', 25, '20–30 min', 'Pencil and paper', 'I believe that…'': 500-word personal essay arguing a position from own experience. Opinion + narrative combined.', 'This refines the precision your child now needs for writing, drawing and detailed work at school. Talk about how they approached it rather than whether they got it right; the strategy is the valuable part.', 'AOTA Fine Motor Development; NCERT Foundational Literacy; IAP'),
  ('woodworking-y5_9', 'motor'::domain, 'y5_9'::age_band, 'Woodworking', 'A practical challenge that builds fine motor precision and control.', 25, '20–30 min', 'Soft wood, hand saw, sandpaper, nails or glue', 'Under supervision: saw, sand, and glue or nail a simple joint. Real tool use + material understanding.', 'Fine motor control at this age is about accuracy and endurance rather than basic ability. Let your child attempt it independently first, and offer help only when they ask or genuinely stall.', 'AOTA Fine Motor Development; NCERT Foundational Literacy; IAP'),
  ('animated-flip-book-y5_9', 'motor'::domain, 'y5_9'::age_band, 'Animated Flip Book', 'An activity that develops drawing accuracy and detail.', 18, '15–20 min', 'Blank booklet or stapled paper + pencil', 'Draw 30 frames of a moving image. Animation principles: timing, squash, stretch, arcs.', 'This refines the precision your child now needs for writing, drawing and detailed work at school. Let your child attempt it independently first, and offer help only when they ask or genuinely stall.', 'AOTA Fine Motor Development; NCERT Foundational Literacy; IAP'),
  ('simple-cushion-cover-y5_9', 'motor'::domain, 'y5_9'::age_band, 'Simple Cushion Cover', 'A skill-building activity focused on cutting accuracy.', 25, '20–30 min', 'Fabric, needle, thread, stuffing', 'Measure, cut, pin, sew three sides, stuff, sew fourth side. A complete sewing project from start to finish.', 'Fine motor control at this age is about accuracy and endurance rather than basic ability. Let your child attempt it independently first, and offer help only when they ask or genuinely stall.', 'AOTA Fine Motor Development; NCERT Foundational Literacy; IAP'),
  ('programme-simple-app-y5_9', 'motor'::domain, 'y5_9'::age_band, 'Programme Simple App', 'A skill-building activity focused on fine motor precision and control.', 25, '20–30 min', 'Computer with Scratch', 'A fully functional quiz or animation with at least 3 scenes and user input. Logic, sequence, and debugging combined.', 'This refines the precision your child now needs for writing, drawing and detailed work at school. Talk about how they approached it rather than whether they got it right; the strategy is the valuable part.', 'AOTA Fine Motor Development; NCERT Foundational Literacy; IAP'),
  ('plaster-into-mould-y5_9', 'motor'::domain, 'y5_9'::age_band, 'Plaster into Mould', 'An activity that develops fine motor precision and control.', 18, '15–20 min', 'Plaster of Paris, mould (clay or plastic)', 'Pour plaster into a mould; wait; remove. Casting + material science: liquid becomes solid as crystals form.', 'This refines the precision your child now needs for writing, drawing and detailed work at school. Talk about how they approached it rather than whether they got it right; the strategy is the valuable part.', 'AOTA Fine Motor Development; NCERT Foundational Literacy; IAP'),
  ('read-classic-novel-y5_9', 'communication'::domain, 'y5_9'::age_band, 'Read Classic Novel', 'An activity that develops reading development.', 25, '20–30 min', 'Adapted classic novel', 'Adapted classic: Treasure Island, Alice in Wonderland, 20,000 Leagues. Literature with historical and cultural context.', 'Language now becomes a tool for thinking, explaining and reading, and this strengthens all three. Expect them to want to do it their own way, and let them where you can.', 'ASHA Speech and Language Milestones; NCERT Foundational Literacy and Numeracy; IAP'),
  ('write-biography-y5_9', 'communication'::domain, 'y5_9'::age_band, 'Write Biography', 'An activity that develops written expression.', 25, '20–30 min', 'Reference material + pencil and paper', 'Write a 400-word biography of a person they admire. Chronological structure + factual writing + sourcing.', 'Being able to explain their thinking out loud helps children organise it, which is why talk matters at this age. Talk about how they approached it rather than whether they got it right; the strategy is the valuable part.', 'ASHA Speech and Language Milestones; NCERT Foundational Literacy and Numeracy; IAP'),
  ('pr-cis-writing-y5_9', 'communication'::domain, 'y5_9'::age_band, 'Précis Writing', 'A skill-building activity focused on reading development.', 18, '15–20 min', '200-word passage + pencil and paper', 'Reduce a 200-word passage to 60 words, keeping all key points. Compression + selection = advanced literacy.', 'Being able to explain their thinking out loud helps children organise it, which is why talk matters at this age. Talk about how they approached it rather than whether they got it right; the strategy is the valuable part.', 'ASHA Speech and Language Milestones; NCERT Foundational Literacy and Numeracy; IAP'),
  ('active-passive-voice-y5_9', 'communication'::domain, 'y5_9'::age_band, 'Active Passive Voice', 'A practical challenge that builds written expression.', 8, '5–10 min', 'Printed sentences', 'The dog bit the man'' vs ''The man was bitten by the dog.'' Transform 5 sentences between voices.', 'Language now becomes a tool for thinking, explaining and reading, and this strengthens all three. Let your child attempt it independently first, and offer help only when they ask or genuinely stall.', 'ASHA Speech and Language Milestones; NCERT Foundational Literacy and Numeracy; IAP'),
  ('read-poetry-aloud-y5_9', 'communication'::domain, 'y5_9'::age_band, 'Read Poetry Aloud', 'An activity that develops reading development.', 13, '10–15 min', 'Short poem', 'Memorise a short poem and perform it with expression to an audience. Oral language + memory + performance.', 'Being able to explain their thinking out loud helps children organise it, which is why talk matters at this age. Expect them to want to do it their own way, and let them where you can.', 'ASHA Speech and Language Milestones; NCERT Foundational Literacy and Numeracy; IAP'),
  ('analyse-news-article-y5_9', 'communication'::domain, 'y5_9'::age_band, 'Analyse News Article', 'A skill-building activity focused on reading development.', 13, '10–15 min', 'Current news article', 'Author, publication, date, claim, evidence given, potential bias. Critical news literacy: 5-question analysis.', 'This supports the vocabulary and expression that school will increasingly demand. Let your child attempt it independently first, and offer help only when they ask or genuinely stall.', 'ASHA Speech and Language Milestones; NCERT Foundational Literacy and Numeracy; IAP'),
  ('story-from-prompt-y5_9', 'communication'::domain, 'y5_9'::age_band, 'Story from Prompt', 'A skill-building activity focused on narrative structure and retelling.', 18, '15–20 min', 'Pencil and paper', 'Open prompt: ''The door appeared overnight where there had never been a door.'' Free creative writing from constraint.', 'Being able to explain their thinking out loud helps children organise it, which is why talk matters at this age. Let your child attempt it independently first, and offer help only when they ask or genuinely stall.', 'ASHA Speech and Language Milestones; NCERT Foundational Literacy and Numeracy; IAP'),
  ('homage-writing-y5_9', 'communication'::domain, 'y5_9'::age_band, 'Homage Writing', 'A skill-building activity focused on written expression.', 18, '15–20 min', 'Pencil and paper + chosen author''s book', 'Write a story in the style of a favourite author. Style analysis + imitation = advanced literary understanding.', 'This supports the vocabulary and expression that school will increasingly demand. Expect them to want to do it their own way, and let them where you can.', 'ASHA Speech and Language Milestones; NCERT Foundational Literacy and Numeracy; IAP'),
  ('long-division-i-y5_9', 'cognitive'::domain, 'y5_9'::age_band, 'Long Division I', 'A practical challenge that builds reasoning, planning and problem-solving.', 8, '5–10 min', 'Pencil and paper', '256 ÷ 8 = 32. Place-value understanding applied to division. Estimate first, then calculate, then check.', 'This develops the planning and reasoning that increasingly demanding schoolwork will require. Expect them to want to do it their own way, and let them where you can.', 'NCERT Foundational Literacy and Numeracy; Harvard Center on the Developing Child; IAP'),
  ('algebra-introduction-y5_9', 'cognitive'::domain, 'y5_9'::age_band, 'Algebra Introduction', 'A practical challenge that builds number and early mathematical thinking.', 8, '5–10 min', 'Pencil and paper', '4 + x = 9. What is x? Unknown number in a known relationship. Algebra as a ''find the missing piece'' problem.', 'This develops the planning and reasoning that increasingly demanding schoolwork will require. Talk about how they approached it rather than whether they got it right; the strategy is the valuable part.', 'NCERT Foundational Literacy and Numeracy; Harvard Center on the Developing Child; IAP'),
  ('geometry-area-perimeter-y5_9', 'cognitive'::domain, 'y5_9'::age_band, 'Geometry Area Perimeter', 'A skill-building activity focused on scientific reasoning.', 8, '5–10 min', 'Ruler and simple shapes drawn on paper', 'Both for the same shape. Why are they different? Distinguish the two concepts concretely before abstractly.', 'At this age children can genuinely think through a problem, and doing so builds the habit of persisting with hard things. Expect them to want to do it their own way, and let them where you can.', 'NCERT Foundational Literacy and Numeracy; Harvard Center on the Developing Child; IAP'),
  ('human-geography-y5_9', 'cognitive'::domain, 'y5_9'::age_band, 'Human Geography', 'A skill-building activity focused on pattern and sequence reasoning.', 13, '10–15 min', 'Simple world map', 'Why do most people live near rivers and coasts? Map evidence + reasoning about human patterns.', 'This develops the planning and reasoning that increasingly demanding schoolwork will require. Expect them to want to do it their own way, and let them where you can.', 'NCERT Foundational Literacy and Numeracy; Harvard Center on the Developing Child; IAP'),
  ('vs-physical-change-y5_9', 'cognitive'::domain, 'y5_9'::age_band, 'vs Physical Change', 'An activity that develops classification and logical grouping.', 13, '10–15 min', 'Candle, apple, water, paper', 'Burning = chemical. Cutting = physical. Test 5 household processes and classify. Observable evidence of change.', 'This develops the planning and reasoning that increasingly demanding schoolwork will require. Let your child attempt it independently first, and offer help only when they ask or genuinely stall.', 'NCERT Foundational Literacy and Numeracy; Harvard Center on the Developing Child; IAP'),
  ('hypothesis-test-y5_9', 'cognitive'::domain, 'y5_9'::age_band, 'Hypothesis Test', 'A skill-building activity focused on scientific reasoning.', 18, '15–20 min', 'Any testable household experiment', 'Write a formal hypothesis: ''I think X will happen because Y.'' Test it. Write results and conclusion. Science protocol.', 'Understanding at this stage grows from working things out rather than being told the answer. Expect them to want to do it their own way, and let them where you can.', 'NCERT Foundational Literacy and Numeracy; Harvard Center on the Developing Child; IAP'),
  ('social-norms-pressures-y5_9', 'social_emotional'::domain, 'y5_9'::age_band, 'Social Norms Pressures', 'A skill-building activity focused on friendship and social navigation.', 8, '5–10 min', 'None', 'What do you do when your friends want you to do something you''re uncomfortable with?'' Social pressure navigation.', 'Social and emotional skills at this age predict how school goes as much as academic ability does. Talk about how they approached it rather than whether they got it right; the strategy is the valuable part.', 'CASEL Social-Emotional Framework; NAEYC Developmentally Appropriate Practice; IAP'),
  ('empathy-difference-y5_9', 'social_emotional'::domain, 'y5_9'::age_band, 'Empathy Difference', 'An activity that develops empathy and perspective-taking.', 8, '5–10 min', 'None', 'Tell me about someone at school who is very different from you. What might their life be like?'' Imaginative empathy.', 'Social and emotional skills at this age predict how school goes as much as academic ability does. Expect them to want to do it their own way, and let them where you can.', 'CASEL Social-Emotional Framework; NAEYC Developmentally Appropriate Practice; IAP'),
  ('own-mental-health-y5_9', 'social_emotional'::domain, 'y5_9'::age_band, 'Own Mental Health', 'A skill-building activity focused on emotional regulation and self-awareness.', 8, '5–10 min', 'None', 'What are 3 things you do when you''re feeling low? What works best?'' Personal mental health toolkit building.', 'Your child can now reflect on their own behaviour, which makes real emotional learning possible. Let your child attempt it independently first, and offer help only when they ask or genuinely stall.', 'CASEL Social-Emotional Framework; NAEYC Developmentally Appropriate Practice; IAP'),
  ('understand-consent-y5_9', 'social_emotional'::domain, 'y5_9'::age_band, 'Understand Consent', 'A skill-building activity focused on social understanding and self-regulation.', 8, '5–10 min', 'None', 'What does it mean for something to be OK with everyone involved?'' Age-appropriate consent framing for all contexts.', 'This supports the friendships, fairness and self-control that become central once children are in a classroom. Talk about how they approached it rather than whether they got it right; the strategy is the valuable part.', 'CASEL Social-Emotional Framework; NAEYC Developmentally Appropriate Practice; IAP'),
  ('handle-exclusion-constructively-y5_9', 'social_emotional'::domain, 'y5_9'::age_band, 'Handle Exclusion Constructively', 'An activity that develops social understanding and self-regulation.', 8, '5–10 min', 'None', 'When you were left out, what did you do? What else could you have done?'' Exclusion is universal and manageable.', 'This supports the friendships, fairness and self-control that become central once children are in a classroom. Talk about how they approached it rather than whether they got it right; the strategy is the valuable part.', 'CASEL Social-Emotional Framework; NAEYC Developmentally Appropriate Practice; IAP'),
  ('be-honest-friend-y5_9', 'social_emotional'::domain, 'y5_9'::age_band, 'Be Honest Friend', 'A skill-building activity focused on friendship and social navigation.', 8, '5–10 min', 'None', 'Would you tell your friend if they had spinach in their teeth? What about something bigger?'' Kindness + honesty.', 'Your child can now reflect on their own behaviour, which makes real emotional learning possible. Let your child attempt it independently first, and offer help only when they ask or genuinely stall.', 'CASEL Social-Emotional Framework; NAEYC Developmentally Appropriate Practice; IAP'),
  ('astronomy-scale-model-y5_9', 'cognitive'::domain, 'y5_9'::age_band, 'Astronomy Scale Model', 'An activity that develops natural sensory environments.', 25, '20–30 min', 'Balls of varied sizes, outdoor space', 'Build a scale model of the solar system outdoors. The distances are more powerful than any diagram. Science + awe.', 'This supports regulation and focus, which matters more once formal learning begins. Let your child attempt it independently first, and offer help only when they ask or genuinely stall.', 'AOTA Sensory Integration; Ayres Sensory Integration framework; IAP'),
  ('kombucha-or-kefir-y5_9', 'cognitive'::domain, 'y5_9'::age_band, 'Kombucha or Kefir', 'An activity that develops smell and taste discrimination.', null, 'Ongoing', 'Starter culture, tea/milk, jar', 'Fermented drink making. Living cultures + nutrition science + patience. Biology you can taste.', 'This supports regulation and focus, which matters more once formal learning begins. Talk about how they approached it rather than whether they got it right; the strategy is the valuable part.', 'AOTA Sensory Integration; Ayres Sensory Integration framework; IAP'),
  ('pressure-force-experiment-y5_9', 'cognitive'::domain, 'y5_9'::age_band, 'Pressure Force Experiment', 'An activity that develops sensory exploration through water.', 13, '10–15 min', 'Balloons, nails in a board (adult-made)', 'Bed of nails principle: one nail vs many nails. Pressure = force/area. Demonstrate with a balloon on a nail board.', 'Sensory-rich activity gives children a break from cognitive demand while still developing skill. Talk about how they approached it rather than whether they got it right; the strategy is the valuable part.', 'AOTA Sensory Integration; Ayres Sensory Integration framework; IAP'),
  ('dyeing-natural-plants-y5_9', 'cognitive'::domain, 'y5_9'::age_band, 'Dyeing Natural Plants', 'A skill-building activity focused on sensory discrimination and integration.', 25, '20–30 min', 'Onion skins/turmeric, fabric, water, pot', 'Onion skins, turmeric, woad. Plant-based dyes on fabric. Chemistry of natural colour in a sensory-rich process.', 'Physical and sensory input remains important at this age, particularly for children who sit still for long periods at school. Expect them to want to do it their own way, and let them where you can.', 'AOTA Sensory Integration; Ayres Sensory Integration framework; IAP'),
  ('micro-gardening-y5_9', 'cognitive'::domain, 'y5_9'::age_band, 'Micro-Gardening', 'A practical challenge that builds natural sensory environments.', null, 'Ongoing', 'Jar, mesh lid, seeds (lentils or mung beans)', 'Grow bean or lentil sprouts in a jar with mesh lid. Harvest in 3–5 days. Speed of growth makes observation immediate.', 'Physical and sensory input remains important at this age, particularly for children who sit still for long periods at school. Talk about how they approached it rather than whether they got it right; the strategy is the valuable part.', 'AOTA Sensory Integration; Ayres Sensory Integration framework; IAP'),
  ('own-calendar-week-y5_9', 'social_emotional'::domain, 'y5_9'::age_band, 'Own Calendar Week', 'A practical challenge that builds organising self and belongings.', 8, '5–10 min', 'Blank weekly planner', 'Write all commitments, deadlines, and personal time into a weekly planner independently.', 'This develops the organisation and self-management that school increasingly demands. Expect them to want to do it their own way, and let them where you can.', 'AOTA Activities of Daily Living; NCERT Foundational Stage; IAP'),
  ('emergency-preparedness-y5_9', 'social_emotional'::domain, 'y5_9'::age_band, 'Emergency Preparedness', 'A practical challenge that builds simple food preparation.', 8, '5–10 min', 'None', 'Know the emergency number (112 in India), when to call, what to say. Practise the call script with a parent.', 'This develops the organisation and self-management that school increasingly demands. Talk about how they approached it rather than whether they got it right; the strategy is the valuable part.', 'AOTA Activities of Daily Living; NCERT Foundational Stage; IAP'),
  ('organise-sports-game-y6_0', 'motor'::domain, 'y6_0'::age_band, 'Organise Sports Game', 'A practical challenge that builds coordination, strength and control.', 25, '20–30 min', 'Sports equipment of choice', 'Plan a game for 4+ players: explain rules, assign roles, referee the first 5 minutes. Leadership + organisation.', 'Physical activity now supports concentration, sleep and mood as much as it supports strength. Expect them to want to do it their own way, and let them where you can.', 'WHO Physical Activity Guidelines (5–17); AAP Sports and Fitness; IAP'),
  ('swim-full-length-y6_0', 'motor'::domain, 'y6_0'::age_band, 'Swim Full Length', 'An activity that develops ball control with the feet.', 18, '15–20 min', 'Swimming pool', 'Always with a trained adult or lifeguard present, swim 25 m with correct technique: head position, arm pull, kick rhythm. Technical swimming, not just distance.', 'Physical activity now supports concentration, sleep and mood as much as it supports strength. Let your child attempt it independently first, and offer help only when they ask or genuinely stall.', 'AAP Water Safety; Indian Swimming Federation basic safety norms; IAP'),
  ('cycling-route-y6_0', 'motor'::domain, 'y6_0'::age_band, 'Cycling Route', 'An activity that develops coordination, strength and control.', 25, '20–30 min', 'Bicycle + map (hand-drawn or printed)', 'Plan a 5-km route, identify landmarks for navigation, execute it. Cartography + cycling + independence.', 'Skills at this age become more accurate and more strategic, and this is the kind of practice that develops both. Talk about how they approached it rather than whether they got it right; the strategy is the valuable part.', 'WHO Physical Activity Guidelines (5–17); AAP Sports and Fitness; IAP'),
  ('field-jumping-event-y6_0', 'motor'::domain, 'y6_0'::age_band, 'Field Jumping Event', 'An activity that develops jumping power and coordination.', 13, '10–15 min', 'Measuring tape + soft landing surface', 'High jump (scissor technique) or long jump. Technique before distance: approach, take-off, landing.', 'Physical activity now supports concentration, sleep and mood as much as it supports strength. Talk about how they approached it rather than whether they got it right; the strategy is the valuable part.', 'WHO Physical Activity Guidelines (5–17); AAP Sports and Fitness; IAP'),
  ('skateboard-basic-tricks-y6_0', 'motor'::domain, 'y6_0'::age_band, 'Skateboard Basic Tricks', 'An activity that develops ball control with the feet.', 13, '10–15 min', 'Skateboard (supervised)', 'Ollie attempt, kick turn, riding fakie. Skateboarding is a self-directed learning model: watch, try, fail, adjust.', 'Skills at this age become more accurate and more strategic, and this is the kind of practice that develops both. Expect them to want to do it their own way, and let them where you can.', 'WHO Physical Activity Guidelines (5–17); AAP Sports and Fitness; IAP'),
  ('martial-arts-y6_0', 'motor'::domain, 'y6_0'::age_band, 'Martial Arts', 'A skill-building activity focused on coordination, strength and control.', 18, '15–20 min', 'None (or video demonstration)', 'Basic stance, block, strike: even in a single lesson or from a video. Discipline + body control + respect.', 'Skills at this age become more accurate and more strategic, and this is the kind of practice that develops both. Let your child attempt it independently first, and offer help only when they ask or genuinely stall.', 'WHO Physical Activity Guidelines (5–17); AAP Sports and Fitness; IAP'),
  ('choreograph-32-counts-y6_0', 'motor'::domain, 'y6_0'::age_band, 'Choreograph 32 Counts', 'An activity that develops rhythm, sequence and coordination.', 18, '15–20 min', 'Music', 'Choreograph a 32-count sequence to chosen music. Creative composition + timing + memory.', 'Physical activity now supports concentration, sleep and mood as much as it supports strength. Talk about how they approached it rather than whether they got it right; the strategy is the valuable part.', 'WHO Physical Activity Guidelines (5–17); AAP Sports and Fitness; IAP'),
  ('archery-y6_0', 'motor'::domain, 'y6_0'::age_band, 'Archery', 'A practical challenge that builds throwing, catching and aiming accuracy.', 13, '10–15 min', 'Simple bow and safe arrows + target', '3 arrows at a target: how consistent is the grouping? Deliberate practice: aim for consistency before accuracy.', 'Skills at this age become more accurate and more strategic, and this is the kind of practice that develops both. Let your child attempt it independently first, and offer help only when they ask or genuinely stall.', 'WHO Physical Activity Guidelines (5–17); AAP Sports and Fitness; IAP'),
  ('novel-y6_0', 'motor'::domain, 'y6_0'::age_band, 'Novel', 'A practical challenge that builds handwriting control.', 25, '20–30 min', 'Pencil and paper', 'Write the first 1000 words of a longer story. Sustaining a narrative over time without finishing it: beginning.', 'Fine motor control at this age is about accuracy and endurance rather than basic ability. Talk about how they approached it rather than whether they got it right; the strategy is the valuable part.', 'AOTA Fine Motor Development; NCERT Foundational Literacy; IAP'),
  ('mosaic-tile-grouting-y6_0', 'motor'::domain, 'y6_0'::age_band, 'Mosaic Tile Grouting', 'A skill-building activity focused on fastening and self-care dexterity.', 25, '20–30 min', 'Tiles, adhesive, grout, board', 'Place small tiles on cement board; apply and wipe grout. Real mosaic-making technique + sensory experience.', 'The hand skills built here support handwriting, and handwriting fluency frees up attention for thinking. Talk about how they approached it rather than whether they got it right; the strategy is the valuable part.', 'AOTA Fine Motor Development; NCERT Foundational Literacy; IAP'),
  ('paper-airplanes-aerodynamics-y6_0', 'motor'::domain, 'y6_0'::age_band, 'Paper Airplanes Aerodynamics', 'A practical challenge that builds construction and spatial precision.', 18, '15–20 min', 'Paper, pencil, tape measure', 'Build 5 different designs and test each. Record flight time and distance. Which design flies furthest? Why?', 'This refines the precision your child now needs for writing, drawing and detailed work at school. Talk about how they approached it rather than whether they got it right; the strategy is the valuable part.', 'AOTA Fine Motor Development; NCERT Foundational Literacy; IAP'),
  ('sew-stuffed-animal-y6_0', 'motor'::domain, 'y6_0'::age_band, 'Sew Stuffed Animal', 'An activity that develops cutting accuracy.', 25, '20–30 min', 'Fabric, needle, thread, stuffing, scissors', 'Design, cut, pin, sew, stuff, and close a small stuffed animal from scratch. Complete sewing project.', 'Fine motor control at this age is about accuracy and endurance rather than basic ability. Let your child attempt it independently first, and offer help only when they ask or genuinely stall.', 'AOTA Fine Motor Development; NCERT Foundational Literacy; IAP'),
  ('digital-art-y6_0', 'motor'::domain, 'y6_0'::age_band, 'Digital Art', 'A practical challenge that builds drawing accuracy and detail.', 18, '15–20 min', 'Tablet or phone + drawing app', 'Create a scene or character in a drawing app. Digital tools have different affordances from analogue: explore them.', 'Fine motor control at this age is about accuracy and endurance rather than basic ability. Let your child attempt it independently first, and offer help only when they ask or genuinely stall.', 'WHO Screen Time Guidelines (under 5); IAP Screen Time Guidance; IAP'),
  ('leather-tooling-y6_0', 'motor'::domain, 'y6_0'::age_band, 'Leather Tooling', 'An activity that develops fine motor precision and control.', 25, '20–30 min', 'Leather offcut, tooling tools (or nail + hammer)', 'Stamp a pattern into wet leather using a tool. Leatherwork is ancient, tactile, and produces lasting objects.', 'The hand skills built here support handwriting, and handwriting fluency frees up attention for thinking. Expect them to want to do it their own way, and let them where you can.', 'AOTA Fine Motor Development; NCERT Foundational Literacy; IAP'),
  ('read-non-fiction-book-y6_0', 'communication'::domain, 'y6_0'::age_band, 'Read Non-Fiction Book', 'An activity that develops reading development.', 25, '20–30 min', 'Non-fiction book of choice', 'Full non-fiction book on a topic of choice. Note-taking while reading: extract key facts and questions.', 'This supports the vocabulary and expression that school will increasingly demand. Let your child attempt it independently first, and offer help only when they ask or genuinely stall.', 'ASHA Speech and Language Milestones; NCERT Foundational Literacy and Numeracy; IAP')
